@once
<style>
.music-session-workspace *{box-sizing:border-box}.music-session-workspace{color-scheme:light dark;font-family:system-ui,sans-serif;background:#111827;color:#e5e7eb;padding:clamp(1rem,2vw,1.5rem);border-radius:1rem}.music-session-workspace h1,.music-session-workspace h2,.music-session-workspace h3,.music-session-workspace p{margin-top:0}.music-session-workspace h1{font-size:clamp(1.8rem,3vw,2.5rem)}.music-session-workspace h2{font-size:1.2rem}.music-session-workspace label{display:block;margin-bottom:.4rem}.music-session-workspace input,.music-session-workspace select,.music-session-workspace textarea,.music-session-workspace button{font:inherit;box-sizing:border-box}.music-session-workspace input,.music-session-workspace select,.music-session-workspace textarea{max-width:100%;width:100%;border:1px solid #64748b;border-radius:.5rem;padding:.7rem;background:#111827;color:#f8fafc}.music-session-workspace button{border:1px solid #64748b;border-radius:.5rem;min-height:2.75rem;padding:.6rem 1rem;background:#1e293b;color:#f8fafc;cursor:pointer}.music-session-workspace button.primary{background:#a7f3d0;color:#052e16;border-color:#a7f3d0;font-weight:650}.music-session-workspace button:disabled{opacity:.45;cursor:default}.music-session-workspace button:focus-visible,.music-session-workspace input:focus-visible,.music-session-workspace select:focus-visible,.music-session-workspace textarea:focus-visible,.music-session-workspace summary:focus-visible{outline:3px solid #6ee7b7;outline-offset:3px}.music-session-workspace a{color:#a7f3d0}.music-session-workspace .grid{display:grid;grid-template-columns:minmax(14rem,1fr) minmax(0,3fr);gap:1.5rem;align-items:start}.music-session-workspace .grid>*{min-width:0}.music-session-workspace .card{background:#1f2937;border:1px solid #475569;border-radius:1rem;padding:1.25rem;margin-bottom:1rem}.music-session-workspace .row{display:flex;gap:.7rem;align-items:center;flex-wrap:wrap}.music-session-workspace .row>*{max-width:100%}.music-session-workspace .field{margin-bottom:1rem}.music-session-workspace .muted{color:#cbd5e1;font-size:.9rem}.music-session-workspace .status{padding:1rem;border-left:4px solid #6ee7b7;background:#1f2937;margin-bottom:1rem}.music-session-workspace .problem{border-color:#fbbf24}.music-session-workspace ul{padding-left:1.25rem}.music-session-workspace li{margin-bottom:.75rem}.music-session-workspace summary{cursor:pointer;padding:.5rem 0}.music-session-workspace table{min-width:40rem;width:100%;border-collapse:collapse}.music-session-workspace th,.music-session-workspace td{text-align:left;padding:.7rem .4rem;border-bottom:1px solid #475569}.music-session-workspace .scroll{overflow:auto}.music-session-workspace [x-cloak]{display:none!important}@media(max-width:50rem){.music-session-workspace .grid{grid-template-columns:1fr}.music-session-workspace .grid>aside{max-height:18rem;overflow:auto}}
</style>
@endonce
